// Deck intelligence for the ECLIPSE / OPM Flow deck editor: keyword documentation database, line tokenizer,
// document outline, cursor context (keyword / record / item / parameter), diagnostics, autocomplete
// suggestions, record templates, column alignment and schema-driven keyword forms.
// Portable C++17 (no ImGui, no Windows) so it is unit-testable on any platform.
// The keyword documentation (release/keyword_docs.txt) is generated by tools/gen_docs.py from the OPM Flow
// reference manual index of OPM/opm-flow-editor-support (GPL-3.0, https://opm-project.org).
#pragma once
#include <istream>
#include <string_view>
#include <map>
#include <string>
#include <vector>

namespace ressim {
namespace deckintel {

struct Param {
    int index = 0;       // 1-based item index inside its record
    int record = 0;      // 1-based record number for multi-record keywords (0 = every record)
    std::string name, manual, def, unitsField, unitsMetric, desc, valueType, dimension;
    std::vector<std::string> options;
    bool required() const { return def.empty(); }
    bool isString() const { return valueType == "STRING"; }
};

struct KwInfo {
    std::string name, sections, alias, summary, example, sizeKind;
    std::vector<int> recordColumns;   // expected columns per record type (0 = unknown)
    bool variadic = false;            // table keyword: the parameters are repeating columns (SWOF, ...)
    std::vector<Param> params;

    int maxRecord() const;                                  // highest Param::record (0 = single record type)
    int recordType(int recordIndex0) const;                 // 1-based record type of a 0-based record (0 = all)
    std::vector<const Param*> recordParams(int recordIndex0) const;
    const Param* param(int recordIndex0, int itemIndex0) const;
    bool validIn(const std::string& section) const;          // true if unknown sections
};

class Docs {
public:
    static Docs& get();
    bool load(const std::string& path);                      // returns false if the file cannot be read
    bool loadText(std::string_view text);                    // same format, from memory (embedded resource)
    bool loaded() const { return ok_; }
    const KwInfo* find(const std::string& name) const;      // exact (upper-case) name, follows alias_of
    const KwInfo* findRaw(const std::string& name) const;   // without alias resolution
    const std::map<std::string, KwInfo>& all() const { return map_; }
private:
    bool loadStream(std::istream& f);
    std::map<std::string, KwInfo> map_;
    bool ok_ = false;
};

// ------------------------------------------------------------------ lexical level
enum class TK : unsigned char { Word, Number, String, Repeat, Defaults, Slash, Comment };
struct Token {
    int begin = 0, end = 0;  // [begin, end) byte columns
    TK kind = TK::Word;
    int count = 1;           // number of items this token stands for (n*v and n* -> n)
    std::string text;
};
// Tokenizes a deck line. "--" starts a comment; everything after a record terminator '/' is a comment too.
void tokenize(const std::string& line, std::vector<Token>& out);
std::string upper(std::string s);
std::string unquote(const std::string& s);
bool isSectionName(const std::string& upperName);
const std::vector<std::string>& sectionNames();   // RUNSPEC GRID EDIT PROPS REGIONS SOLUTION SUMMARY SCHEDULE
// A keyword line holds one word of up to 8 characters starting in column 1 and nothing else (except a comment).
bool keywordLine(const std::string& line, std::string* name = nullptr);

// ------------------------------------------------------------------ document structure
struct OutlineItem { int line = 0; std::string name; bool section = false; };
struct Outline {
    std::vector<OutlineItem> items;      // keyword lines in document order
    int itemAt(int line) const;          // index of the keyword owning a line (-1 before the first keyword)
    std::string sectionAt(int line) const;
    int bodyEnd(int item, int lineCount) const;   // last line of the body of an item
};
Outline buildOutline(const std::vector<std::string>& lines);

struct Context {
    int item = -1, kwLine = -1;
    std::string keyword, section;
    const KwInfo* info = nullptr;
    bool onKeywordLine = false, inComment = false, arrayKeyword = false;
    int record = 0;           // 0-based record of the keyword
    int itemIndex = -1;       // 0-based item inside the record
    int arrayIndex = -1;      // 0-based value index for array keywords (PORO, ...)
    const Param* param = nullptr;
};
Context contextAt(const std::vector<std::string>& lines, const Outline& outline, int line, int col);

// ------------------------------------------------------------------ diagnostics
struct Diag { int line = 0, col0 = 0, col1 = 0; int severity = 1; std::string text; };   // 0 info, 1 warning, 2 error
std::vector<Diag> lint(const std::vector<std::string>& lines, const Outline& outline);

// ------------------------------------------------------------------ editing help
std::vector<std::string> suggest(const std::vector<std::string>& lines, const Outline& outline, int line, int wordStartCol,
                                 const std::string& prefix, bool* keywordMode = nullptr);
std::vector<std::string> wellNames(const std::vector<std::string>& lines, const Outline& outline);
std::vector<std::string> groupNames(const std::vector<std::string>& lines, const Outline& outline);
int dimensCells(const std::vector<std::string>& lines, const Outline& outline, int* nx = nullptr, int* ny = nullptr, int* nz = nullptr);
std::map<std::string, std::string> pathAliases(const std::vector<std::string>& lines, const Outline& outline);   // PATHS
std::string includePath(const std::vector<std::string>& lines, const Outline& outline, int line);   // INCLUDE/IMPORT at line

// Moves keywords whose text is larger than 'threshold' bytes into include files (Norne-style split decks):
// returns the main deck text; files receives (relative path, content) pairs; relDir is e.g. "INCLUDE".
std::string externalizeLargeKeywords(const std::string& text, const std::string& relDir, const std::string& base, size_t threshold,
                                     std::vector<std::pair<std::string, std::string>>& files);
std::vector<std::string> splitLines(const std::string& text);
std::string joinLines(const std::vector<std::string>& lines, size_t first = 0, size_t last = size_t(-1));

// Body text (without the keyword line) of a ready-to-fill record template, with a "--" column header line.
std::string recordTemplate(const std::string& keyword, int cells = 0);
// Aligns the columns of a keyword body; addHeaders regenerates the "--" column header comment lines.
std::vector<std::string> alignBody(const std::string& keyword, const std::vector<std::string>& body, bool addHeaders);

// ------------------------------------------------------------------ schema-driven keyword forms
struct Form {
    std::string keyword;
    const KwInfo* info = nullptr;
    bool table = false;          // variadic table keyword: rows of 'columns' values per record (table)
    int columns = 0;
    bool terminated = false;     // an empty record "/" closes the list
    std::vector<std::vector<std::string>> records;   // items (defaults expanded to "1*"); tables: flattened values
    bool editable() const;
};
Form parseForm(const std::string& keyword, const std::vector<std::string>& body);
std::vector<std::string> writeForm(const Form& form);   // aligned body lines with column headers

} // namespace deckintel
} // namespace ressim
